codeExamples.java:
public class Main {
    public static void main(String[] args) {
        int score = 85;
        char grade;
        if (score >= 90) {
            grade = 'A';
        } else if (score >= 80) {
            grade = 'B';
        } else {
            grade = 'C';
        }
        System.out.println("Score: " + score + " -> Grade: " + grade);
    }
}

