codeExamples.cpp:
#include <iostream>
int main() {
    int score = 85;
    char grade;
    if (score >= 90) grade = 'A';
    else if (score >= 80) grade = 'B';
    else grade = 'C';
    std::cout << "Score: " << score << " -> Grade: " << grade << std::endl;
    return 0;
}
